INSERT INTO lib_books (category_id, title, author, isbn, description, copies_total, copies_available, rent_per_day, deposit) VALUES
  ((SELECT category_id FROM lib_categories WHERE name='นิยายแฟนตาซี'), 'Harry Potter and the Philosopher''s Stone', 'J. K. Rowling', '9788186775608', 'Turning the envelope over, his hand trembling, Harry saw a purple wax seal bearing a coat of arms; a lion, an eagle, a badger and a snake surrounding a large letter ''H''.', 2, 2, 5, 100),
  ((SELECT category_id FROM lib_categories WHERE name='นิยายแฟนตาซี'), 'A Game of Thrones', 'George R. R. Martin', '9781415900642', 'A Game of Thrones is the inaugural novel in A Song of Ice and Fire, an epic series of fantasy novels crafted by the American author George R. R. Martin. Published on August 1, 1996, this novel introduces readers to the richly detailed world of Westeros and Essos, where political intrigue, power struggles, and magical elements intertwine.', 3, 3, 12, 240),
  ((SELECT category_id FROM lib_categories WHERE name='นิยายแฟนตาซี'), 'A Court of Mist and Fury', 'Sarah J. Maas', '9781664434448', 'Feyre has undergone more trials than one human woman can carry in her heart. Though she''s now been granted the powers and lifespan of the High Fae, she is haunted by her time Under the Mountain and the terrible deeds she performed to save the lives of Tamlin and his people.', 4, 4, 9, 180),
  ((SELECT category_id FROM lib_categories WHERE name='นิยายแฟนตาซี'), 'Nineteen Eighty-Four', 'George Orwell', '9780140862546', 'Nineteen Eighty-Four: A Novel, often referred to as 1984, is a dystopian social science fiction novel by the English novelist George Orwell (the pen name of Eric Arthur Blair). It was published on 8 June 1949 by Secker & Warburg as Orwell''s ninth and final book completed in his lifetime. Thematically, Nineteen Eighty-Four centres on the consequences of totalitarianism, mass surveillance, and repressive regimentation of persons and behaviours within society. Orwell, himself a democratic socialist, modelled the authoritarian government in the novel after Stalinist Russia. More broadly, the novel examines the role of truth and facts within politics and the ways in which they are manipulated.', 2, 2, 6, 120),
  ((SELECT category_id FROM lib_categories WHERE name='นิยายแฟนตาซี'), 'The Lightning Thief', 'Rick Riordan', '9780641723445', 'Twelve-year-old Percy Jackson is on the most dangerous quest of his life. With the help of a satyr and a daughter of Athena, Percy must journey across the United States to catch a thief who has stolen the original weapon of mass destruction—Zeus’ master bolt. Along the way, he must face a host of mythological enemies determined to stop him. Most of all, he must come to terms with a father he has never known, and an Oracle that has warned him of betrayal by a friend.', 3, 3, 13, 260),
  ((SELECT category_id FROM lib_categories WHERE name='นิยายแฟนตาซี'), 'Harry Potter and the Chamber of Secrets', 'J. K. Rowling', '9780747545774', 'Throughout the summer holidays after his first year at Hogwarts School of Witchcraft and Wizardry, Harry Potter has been receiving sinister warnings from a house-elf called Dobby.', 4, 4, 10, 200),
  ((SELECT category_id FROM lib_categories WHERE name='นิยายแฟนตาซี'), 'Harry Potter and the Deathly Hallows', 'J. K. Rowling', '9783867176651', 'Harry Potter is leaving Privet Drive for the last time. But as he climbs into the sidecar of Hagrid’s motorbike and they take to the skies, he knows Lord Voldemort and the Death Eaters will not be far behind.', 2, 2, 7, 140),
  ((SELECT category_id FROM lib_categories WHERE name='นิยายแฟนตาซี'), 'The Cruel Prince', 'Holly Black', '9781471407031', 'GUARD YOUR MORTAL HEART.', 3, 3, 14, 280),
  ((SELECT category_id FROM lib_categories WHERE name='นิยายแฟนตาซี'), 'Harry Potter and the Prisoner of Azkaban', 'J. K. Rowling', '9788475967769', 'For Harry Potter, it’s the start of another far-from-ordinary year at Hogwarts when the Knight Bus crashes through the darkness and comes to an abrupt halt in front of him.', 4, 4, 11, 220),
  ((SELECT category_id FROM lib_categories WHERE name='นิยายแฟนตาซี'), 'The Hobbit', 'J.R.R. Tolkien', '9782253049418', 'The Hobbit is a tale of high adventure, undertaken by a company of dwarves in search of dragon-guarded gold. A reluctant partner in this perilous quest is Bilbo Baggins, a comfort-loving unambitious hobbit, who surprises even himself by his resourcefulness and skill as a burglar.', 2, 2, 8, 160),
  ((SELECT category_id FROM lib_categories WHERE name='นิยายแฟนตาซี'), 'Harry Potter and the Goblet of Fire', 'J. K. Rowling', '9788000012537', 'The fourth book in the Harry Potter franchise sees Harry returning for his fourth year at Hogwarts School of Witchcraft and Wizardry, along with his friends, Ron and Hermione . There is an upcoming tournament between the three major schools of magic, with one participant selected from each school by the Goblet of Fire. When Harry''s name is drawn, even though he is not eligible and is a fourth player, he must compete in the dangerous contest.', 3, 3, 5, 100),
  ((SELECT category_id FROM lib_categories WHERE name='นิยายแฟนตาซี'), 'Harry Potter and the Order of the Phoenix', 'J. K. Rowling', '9788372780966', 'After the Dementors’ attack on his cousin Dudley, Harry knows he is about to become Voldemort’s next target.', 4, 4, 12, 240),
  ((SELECT category_id FROM lib_categories WHERE name='นิยายแฟนตาซี'), 'A Court of Thorns and Roses', 'Sarah J. Maas', '9788408268192', 'When nineteen-year-old huntress Feyre kills a wolf in the woods, a terrifying creature arrives to demand retribution. Dragged to a treacherous magical land she knows about only from legends, Feyre discovers that her captor is not truly a beast, but one of the lethal, immortal faeries who once ruled her world.', 2, 2, 9, 180),
  ((SELECT category_id FROM lib_categories WHERE name='นิยายแฟนตาซี'), 'Charlotte''s Web', 'E. B. White', '9789750821714', 'Charlotte''s Web is a book of children''s literature by American author E. B. White and illustrated by Garth Williams; it was published on October 15, 1952, by Harper & Brothers. The novel tells the story of a livestock pig named Wilbur and his friendship with a barn spider named Charlotte. When Wilbur is in danger of being slaughtered by the farmer, Charlotte writes messages praising Wilbur (such as "Some Pig") in her web in order to persuade the farmer to let him live.', 3, 3, 6, 120),
  ((SELECT category_id FROM lib_categories WHERE name='นิยายแฟนตาซี'), 'Harry Potter and the Half-Blood Prince', 'J. K. Rowling', '9781408855706', 'One summer night, when Dumbledore arrives at Privet Drive to collect Harry Potter, his wand hand is blackened and shriveled, but he will not reveal why.', 4, 4, 13, 260),
  ((SELECT category_id FROM lib_categories WHERE name='นิยายแฟนตาซี'), 'The Eye of the World', 'Robert Jordan', '9781250754738', 'The Wheel of Time turns and Ages come and go, leaving memories that become legend. Legend fades to myth, and even myth is long forgotten when the Age that gave it birth returns again. In the Third Age, an Age of Prophecy, the World and Time themselves hang in the balance. What was, what will be, and what is, may yet fall under the Shadow.', 2, 2, 10, 200),
  ((SELECT category_id FROM lib_categories WHERE name='นิยายแฟนตาซี'), 'Fourth Wing', 'Rebecca Yarros', '9781649376169', 'Twenty-year-old Violet Sorrengail was supposed to enter the Scribe Quadrant, living a quiet life among books and history. Now, the commanding general—also known as her tough-as-talons mother—has ordered Violet to join the hundreds of candidates striving to become the elite of Navarre: dragon riders.', 3, 3, 7, 140),
  ((SELECT category_id FROM lib_categories WHERE name='นิยายแฟนตาซี'), 'Coraline', 'Neil Gaiman', '9781408818619', 'When Coraline steps through a door to find another house strangely similar to her own (only better), things seem marvelous.', 4, 4, 14, 280),
  ((SELECT category_id FROM lib_categories WHERE name='นิยายแฟนตาซี'), 'Charlie and the Chocolate Factory', 'Roald Dahl', '9788481471243', 'Charlie and the Chocolate Factory is a 1964 children''s novel by British author Roald Dahl. The story features the adventures of young Charlie Bucket inside the chocolate factory of eccentric chocolatier Willy Wonka.', 2, 2, 11, 220),
  ((SELECT category_id FROM lib_categories WHERE name='นิยายแฟนตาซี'), 'The Fellowship of the Ring', 'J.R.R. Tolkien', '9781500410223', 'One Ring to rule them all, One Ring to find them, One Ring to bring them all and in the darkness bind them.', 3, 3, 8, 160),
  ((SELECT category_id FROM lib_categories WHERE name='นิยายแฟนตาซี'), 'Six of Crows', 'Leigh Bardugo', '9788418359675', 'BOOK ONE of the Six of Crows Duology', 4, 4, 5, 100),
  ((SELECT category_id FROM lib_categories WHERE name='นิยายแฟนตาซี'), 'The Lost Hero', 'Rick Riordan', '9788580570083', 'Jason has a problem. He doesn’t remember anything before waking up on a school bus holding hands with a girl. Apparently she’s his girlfriend Piper, his best friend is a kid named Leo, and they’re all students in the Wilderness School, a boarding school for “bad kids.” What he did to end up here, Jason has no idea―except that everything seems very wrong.', 2, 2, 12, 240),
  ((SELECT category_id FROM lib_categories WHERE name='นิยายแฟนตาซี'), 'Alice''s Adventures in Wonderland', 'Lewis Carroll', '9788477026709', 'Alice''s Adventures in Wonderland (commonly Alice in Wonderland) is an 1865 English children''s novel by Lewis Carroll. A young girl named Alice falls through a rabbit hole into a fantasy world of anthropomorphic creatures. It is seen as an example of the literary nonsense genre.', 3, 3, 9, 180),
  ((SELECT category_id FROM lib_categories WHERE name='นิยายแฟนตาซี'), 'The Midnight Library', 'Matt Haig', '9798885792226', 'Between life and death there is a library, and within that library, the shelves go on forever. Every book provides a chance to try another life you could have lived. To see how things would be if you had made other choices . . . Would you have done anything different, if you had the chance to undo your regrets?”', 4, 4, 6, 120),
  ((SELECT category_id FROM lib_categories WHERE name='วิทยาศาสตร์'), 'A Brief History of Time', 'Stephen Hawking', '9789879317679', 'Stephen Hawking''s ‘A Brief History of Time has become an international publishing phenomenon. Translated into thirty languages, it has sold over ten million copies worldwide and lives on as a science book that continues to captivate and inspire new readers each year. When it was first published in 1988 the ideas discussed in it were at the cutting edge of what was then known about the universe. In the intervening twenty years there have been extraordinary advances in the technology of observing both the micro- and macro-cosmic world. Indeed, during that time cosmology and the theoretical sciences have entered a new golden age . Professor Hawking is one of the major scientists and thinker...', 2, 2, 13, 260),
  ((SELECT category_id FROM lib_categories WHERE name='วิทยาศาสตร์'), 'A short history of nearly everything', 'Bill Bryson', '9788478713806', 'A Short History of Nearly Everything by American author Bill Bryson is a popular science book that explains some areas of science, using easily accessible language that appeals more so to the general public than many other books dedicated to the subject. It was one of the bestselling popular science books of 2005 in the United Kingdom, selling over 300,000 copies.', 3, 3, 10, 200),
  ((SELECT category_id FROM lib_categories WHERE name='วิทยาศาสตร์'), 'The Man Who Mistook His Wife for a Hat', 'Oliver Sacks', '9780593466674', 'In his most extraordinary book, “one of the great clinical writers of the twentieth century” (The New York Times) recounts the case histories of patients lost in the bizarre, apparently inescapable world of neurological disorders.', 4, 4, 7, 140),
  ((SELECT category_id FROM lib_categories WHERE name='วิทยาศาสตร์'), 'Cosmos', 'Carl Sagan', '9781559603140', 'This book is about science in its broadest human context, how science and civilization grew up together. It is the story of our long journey of discovery and the forces and individuals who helped to shape modern science, including Democritus, Hypatia, Kepler, Newton, Huygens, Champollion, Lowell and Humason. The book also explores spacecraft missions of discovery of the nearby planets, the research in the Library of ancient Alexandria, the human brain, Egyptian hieroglyphics, the origin of life, the death of the Sun, the evolution of galaxies and the origins of matter, suns and worlds. The author retraces the fifteen billion years of cosmic evolution that have transformed matter into life...', 2, 2, 14, 280),
  ((SELECT category_id FROM lib_categories WHERE name='วิทยาศาสตร์'), 'The Demon-Haunted World', 'Carl Sagan', '9780345409461', 'A prescient warning of a future we now inhabit, where fake news stories and Internet conspiracy theories play to a disaffected American populace', 3, 3, 11, 220),
  ((SELECT category_id FROM lib_categories WHERE name='วิทยาศาสตร์'), 'Über die spezielle und die allgemeine Relativitätstheorie', 'Albert Einstein', '9780879759797', 'Einstein''s own explanation of his theory for those who do not have a mathematical background and are unfamiliar with physics.', 4, 4, 8, 160),
  ((SELECT category_id FROM lib_categories WHERE name='วิทยาศาสตร์'), 'Brain Rules', 'John Medina', '9780979777745', 'Most of us have no idea what''s really going on inside our heads. Yet brain scientists have uncovered details every business leader, parent, and teacher should know—such as the brain''s need for physical activity to work at its best.How do we learn? What exactly do sleep and stress do to our brains? Why is multi-tasking a myth? Why is it so easy to forget—and so important to repeat new knowledge? Is it true that men and women have different brains?In Brain Rules, molecular biologist John Medina shares his lifelong interest in how the brain sciences might influence the way we teach our children and the way we work. In each chapter, he describes a Brain Rule—what scientists know for sure abou...', 2, 2, 5, 100),
  ((SELECT category_id FROM lib_categories WHERE name='วิทยาศาสตร์'), 'The Intelligent Man''s Guide to Science', 'Isaac Asimov', '9788401480058', 'Reports on recent advances in the physical and biological sciences to aid the general reader in understanding modern scientific phenomena.', 3, 3, 12, 240),
  ((SELECT category_id FROM lib_categories WHERE name='วิทยาศาสตร์'), 'Siete breves lecciones de física', 'Carlo Rovelli', '9786257118026', 'An introduction to modern physics by a founder of the loop quantum gravity theory shares seven succinct lessons on topics ranging from general relativity and quantum mechanics to elementary particles and black holes.', 4, 4, 9, 180),
  ((SELECT category_id FROM lib_categories WHERE name='วิทยาศาสตร์'), 'Bad Science', 'Ben Goldacre', '9781407438719', 'Full of spleen, this will be a hilarious, invigorating and informative journey through the world of Bad Science.When Dr Ben Goldacre saw someone on daytime TV dipping her feet in an ''Aqua Detox'' footbath, releasing her toxins into the water, turning it brown, he thought he''d try the same at home. ''Like some kind of Johnny Ball cum Witchfinder General'', using his girlfriend''s Barbie doll, he gently passed an electrical current through the warm salt water. It turned brown. In his words: ''before my very eyes, the world''s first Detox Barbie was sat, with her feet in a pool of brown sludge, purged of a weekend''s immorality.''Dr Ben Goldacre is the author of the Bad Science column in the Guardia...', 2, 2, 6, 120),
  ((SELECT category_id FROM lib_categories WHERE name='วิทยาศาสตร์'), 'The Fabric of the Cosmos', 'Brian Greene', '9780375727207', 'A magnificent challenge to conventional ideas'' Financial Times''I thoroughly enjoyed this book. It manages to be both challenging and entertaining: it is highly recommended'' the Independent''(Greene) send(s) the reader''s imagination hurtling through the universe on an astonishing ride. As a popularizer of exquisitely abstract science, he is both a skilled and kindly explicator'' the New York Times''Greene is as elegant as ever, cutting through the fog of complexity with insight and clarity; space and time become putty in his hands'' Los Angeles Times Book Review', 3, 3, 13, 260),
  ((SELECT category_id FROM lib_categories WHERE name='วิทยาศาสตร์'), 'The Magic of Reality', 'Richard Dawkins', '9780857531940', 'What are things made of? What is the sun? Why is there night and day, winter and summer? Why do bad things happen? Are we alone?', 4, 4, 10, 200),
  ((SELECT category_id FROM lib_categories WHERE name='วิทยาศาสตร์'), 'Billions and billions', 'Carl Sagan', '9788535911947', 'In this book, his last, Carl Sagan shows once again his extraordinary ability to interpret the mysteries of life and the majesty of the universe for the general reader.', 2, 2, 7, 140),
  ((SELECT category_id FROM lib_categories WHERE name='วิทยาศาสตร์'), 'The Singularity Is Near', 'Ray Kurzweil', '9780593163269', 'For over three decades, Ray Kurzweil has been one of the most respected and provocative advocates of the role of technology in our future. In his classic The Age of Spiritual Machines, he argued that computers would soon rival the full range of human intelligence at its best. Now he examines the next step in this inexorable evolutionary process: the union of human and machine, in which the knowledge and skills embedded in our brains will be combined with the vastly greater capacity, speed, and knowledge-sharing ability of our creations.', 3, 3, 14, 280),
  ((SELECT category_id FROM lib_categories WHERE name='วิทยาศาสตร์'), 'Your inner fish', 'Neil Shubin', '9789046805268', 'Why do we look the way we do? What does the human hand have in common with the wing of a fly? Are breasts, sweat glands, and scales connected in some way? To better understand the inner workings of our bodies and to trace the origins of many of today''s most common diseases, we have to turn to unexpected sources: worms, flies, and even fish.Neil Shubin, a leading paleontologist and professor of anatomy who discovered Tiktaalik--the "missing link" that made headlines around the world in April 2006--tells the story of evolution by tracing the organs of the human body back millions of years, long before the first creatures walked the earth. By examining fossils and DNA, Shubin shows us that o...', 4, 4, 11, 220),
  ((SELECT category_id FROM lib_categories WHERE name='วิทยาศาสตร์'), 'The Human Body', 'Isaac Asimov', '9780451627070', '"In writing a book about the human body there is the great advantage that all the readers know what a human body is." Who but Isaac Asimov would begin a serious textbook in such a jovial way? Sketching first the biological order of the evolutionary process until he reaches its apogee, man, he establishes the place of homo sapens in Nature''s scheme. Then, limb by limb, organ by organ, occasionally cell by cell, he describes man internally and externally in terms of his chemical and structural nature. Throughout, technical terminology is followed by an informal phonetic breakdown and etymological identification. By contrasting man''s posture with that of various animals, Asimov clearly and e...', 2, 2, 8, 160),
  ((SELECT category_id FROM lib_categories WHERE name='วิทยาศาสตร์'), 'Stuff Matters', 'Mark Miodownik', '9780544236042', '"Why is glass see-through? What makes elastic stretchy? Why does a paperclip bend? Why does any material look and behave the way it does?With clarity and humor, world-leading materials scientist Mark Miodownik answers all the questions you''ve ever had about your pens, spoons, and razor blades, while also introducing a whole world full of materials you''ve never even heard of: the diamond five times the size of Earth; concrete cloth that can be molded into any shape; and graphene, the thinnest, strongest, stiffest material in existence--only a single atom thick.Stuff Matters tells enthralling stories that explain the science and history of materials. From the teacup to the jet engine, the s...', 3, 3, 5, 100),
  ((SELECT category_id FROM lib_categories WHERE name='วิทยาศาสตร์'), 'The Human Brain', 'Isaac Asimov', '9780451628671', 'Provides an explanation of the human brain, including its divisions, systems, and functions.', 4, 4, 12, 240),
  ((SELECT category_id FROM lib_categories WHERE name='วิทยาศาสตร์'), 'Bonk', 'Mary Roach', '9781423316701', 'Few things are as fundamental to human happiness as sex, and few writers are as entertaining about the subject as Mary Roach. Can a woman think herself to orgasm? Is your penis three inches longer than you think? Why doesn''t Viagra help women - or, for that matter, pandas? Does orgasm boost fertility? Or cure hiccups? The study of sexual physiology - what happens, and why, and how to make it happen better - has been taking place behind closed doors for hundreds of years. In this fascinating and funny book, Mary Roach steps inside laboratories, brothels, pig farms, sex-toy R&D labs - even Alfred Kinsey''s attic - to tell us everything we wanted to know about sex, and a lot we''d never even t...', 2, 2, 9, 180),
  ((SELECT category_id FROM lib_categories WHERE name='วิทยาศาสตร์'), 'Parallel Worlds', 'Michio Kaku', '9780385509862', 'Is our universe dying? Could there be other universes?In Parallel Worlds, world-renowned physicist and bestselling author Michio Kaku--an author who "has a knack for bringing the most ethereal ideas down to earth" (Wall Street Journal)--takes readers on a fascinating tour of cosmology, M-theory, and its implications for the fate of the universe.In his first book of physics since Hyperspace, Michio Kaku begins by describing the extraordinary advances that have transformed cosmology over the last century, and particularly over the last decade, forcing scientists around the world to rethink our understanding of the birth of the universe, and its ultimate fate. In Dr. Kaku''s eyes, we are livi...', 3, 3, 6, 120),
  ((SELECT category_id FROM lib_categories WHERE name='วิทยาศาสตร์'), 'Spillover', 'David Quammen', '9781491545089', 'This work examines the emergence and causes of new diseases all over the world, describing a process called "spillover" where illness originates in wild animals before being passed to humans and discusses the potential for the next huge pandemic. The emergence of strange new diseases is a frightening problem that seems to be getting worse. In this age of speedy travel, it threatens a worldwide pandemic. We hear news reports of Ebola, SARS, AIDS, and something called Hendra killing horses and people in Australia; but those reports miss the big truth that such phenomena are part of a single pattern. The bugs that transmit these diseases share one thing: they originate in wild animals and pa...', 4, 4, 13, 260),
  ((SELECT category_id FROM lib_categories WHERE name='วิทยาศาสตร์'), 'Quantum Mechanics', 'Leonard Susskind', '9780141977812', 'Explains the theory and associated mathematics of quantum mechanics, discussing topics ranging from uncertainty and time dependence to particle and wave states.', 2, 2, 10, 200),
  ((SELECT category_id FROM lib_categories WHERE name='วิทยาศาสตร์'), 'The Human Use of Human Beings', 'Norbert Wiener', '9781853430756', '"Only a few books stand as landmarks in social and scientific upheaval. Norbert Wiener''s classic is one in that small company. Founder of the science of cybernetics--the study of the relationship between computers and the human nervous system--Wiener was widely misunderstood as one who advocated the automation of human life. As this book reveals, his vision was much more complex and interesting. He hoped that machines would release people from relentless and repetitive drudgery in order to achieve more creative pursuits. At the same time he realized the danger of dehumanizing and displacement. His book examines the implications of cybernetics for education, law, language, science, technol...', 3, 3, 7, 140),
  ((SELECT category_id FROM lib_categories WHERE name='วิทยาศาสตร์'), 'Parasite Rex', 'Carl Zimmer', '9780099457992', 'A look inside the often hidden world of parasites turns the clock back to the beginning of life on Earth to answer key questions about these highly evolved and resilient life forms.', 4, 4, 14, 280),
  ((SELECT category_id FROM lib_categories WHERE name='ประวัติศาสตร์'), 'Sapiens', 'Yuval Noah Harari', '9781716994982', 'From a renowned historian comes a groundbreaking narrative of humanity’s creation and evolution—a #1 international bestseller—that explores the ways in which biology and history have defined us and enhanced our understanding of what it means to be “human.”', 2, 2, 11, 220),
  ((SELECT category_id FROM lib_categories WHERE name='ประวัติศาสตร์'), 'Guns, Germs, and Steel', 'Jared Diamond', '9783596145393', 'An epic detective story that offers a gripping expose on why the world is so unequal. Professor Jared Diamond traveled the globe for over 30 years trying to answer this question.', 3, 3, 8, 160),
  ((SELECT category_id FROM lib_categories WHERE name='ประวัติศาสตร์'), 'Manifest der Kommunistischen Partei', 'Karl Marx', '9780853459361', 'Available under a Creative Commons Attribution-ShareAlike License: http://www.marxists.org/archive/marx/works/1848/communist-manifesto/', 4, 4, 5, 100),
  ((SELECT category_id FROM lib_categories WHERE name='ประวัติศาสตร์'), 'A history of the modern world', 'R. R. Palmer', '9780072316551', 'Conceived and written as a history of the modern world rather than a truncated Western Civilization book, this text is one of the most highly praised history texts ever published. It has been adopted at more than 1000 schools and has been translated into six languages. Lloyd Kramer joins the author team for this ninth edition that includes two new color inserts highlighting fine art, additional pedagogy to guide students through challenging material, and full, up-to-date inclusion of current events. First published in 1950, translated into six languages, is used in more than 1,000 colleges and universities as well as many high school advanced placement courses. The second edition (1956), ...', 2, 2, 12, 240),
  ((SELECT category_id FROM lib_categories WHERE name='ประวัติศาสตร์'), 'Eichmann in Jerusalem', 'Hannah Arendt', '9781101004760', 'Eichmann in Jerusalem: A Report on the Banality of Evil is a 1963 book by political theorist Hannah Arendt. Arendt, a Jew who fled Germany during Adolf Hitler''s rise to power, reported on Adolf Eichmann''s trial for The New Yorker. A revised and enlarged edition was published in 1964.', 3, 3, 9, 180),
  ((SELECT category_id FROM lib_categories WHERE name='ประวัติศาสตร์'), 'The Souls of Black Folk', 'W. E. B. Du Bois', '9781975500634', 'Du Bois'' 1903 collection of essays is a thoughtful, articulate exploration of the moral and intellectual issues surrounding the perception of blacks within American society.', 4, 4, 6, 120),
  ((SELECT category_id FROM lib_categories WHERE name='ประวัติศาสตร์'), 'Collapse', 'Jared Diamond', '9780713998627', '"In his Pulitzer Prize-winning bestseller Guns, Germs, and Steel, Jared Diamond examined how and why Western civilizations developed the technologies and immunities that allowed them to dominate much of the world. Now, Diamond probes the other side of the equation: What caused some of the great civilizations of the past to collapse into ruin, and what can we learn from their fates?" "As in Guns, Germs, and Steel, Diamond weaves an all-encompassing global thesis through a series of historical-cultural narratives. Moving from the prehistoric Polynesian culture on Easter Island to the formerly flourishing Native American civilizations of the Anasazi and the Maya, the doomed medieval Viking c...', 2, 2, 13, 260),
  ((SELECT category_id FROM lib_categories WHERE name='ประวัติศาสตร์'), 'The Silk Roads', 'Peter Frankopan', '9781408889930', '"Our world was made on and by the Silk Roads. For millennia it was here that East and West encountered each other through trade and conquest, leading to the spread of ideas and cultures, the birth of the world''s great religions, the appetites for foreign goods that drove economies and the growth of nations. From the first cities in Mesopotamia to the growth of Greece and Rome to the depredations by the Mongols and the Black Death to the Great Game and the fall of Communism, the fate of the West has always been inextricably linked to the East. The Silk Roads vividly captures the importance of the networks that crisscrossed the spine of Asia and linked the Atlantic with the Pacific, the Med...', 3, 3, 10, 200),
  ((SELECT category_id FROM lib_categories WHERE name='ประวัติศาสตร์'), 'The Lessons of History', 'Will Durant', '9787220093104', 'Written by the authors of the 10 volume The Story of Civilization, this short (fewer than 120 pages) work notes "events and comments that might illuminate present affairs, future probabilities, the nature of man, and the conduct of states." Its 13 chapters discuss historiography (what is history), history and the earth, history and biology, race, character, morals, religion, economics, socialism, government, war, growth and decay. The final chapter asks, "Is progress real?"', 4, 4, 7, 140),
  ((SELECT category_id FROM lib_categories WHERE name='ประวัติศาสตร์'), 'The Muqaddimah, an introduction to history', 'Ibn Khaldūn', '9780691099460', 'This prolegomenon was written in the 14th century by the Arab scholar Ibn Khaldūn, & laid the intellectual foundations for philosophy of history, sociology, ethnography & economics. This translation was first published in 1958 in three volumes.', 2, 2, 14, 280),
  ((SELECT category_id FROM lib_categories WHERE name='ประวัติศาสตร์'), 'The Alhambra', 'Washington Irving', '9788495856654', 'Verhalen over het gebouwencomplex in Granada, dat eigendom was van de laatste islamitische vorsten in Spanje.', 3, 3, 11, 220),
  ((SELECT category_id FROM lib_categories WHERE name='ประวัติศาสตร์'), 'Traditions & encounters', 'Jerry H. Bentley', '9780073513324', 'Traditions & Encounters: A Brief Global History brings focus to the human experience. It turns the story of world history into a cohesive narrative by putting events into perspective and creating a framework for cross-cultural comparisons. It tells the story of people in history, the traditions they embraced, and the encounters with other cultures that brought about inevitable change. - Back cover.', 4, 4, 8, 160),
  ((SELECT category_id FROM lib_categories WHERE name='ประวัติศาสตร์'), 'The Innocents Abroad', 'Mark Twain', '9780343488949', 'Twain''s letters about his steamship voyage of 1867.', 2, 2, 5, 100),
  ((SELECT category_id FROM lib_categories WHERE name='ประวัติศาสตร์'), 'The Everlasting Man', 'Gilbert Keith Chesterton', '9781603868983', '<p><i>The Everlasting Man</i> is inspired by <a href="https://standardebooks.org/ebooks/h-g-wells">H. G. Wells’</a> <i>The Outline of History</i>, which explains the history of mankind and religion as solely a product of natural selection and other material causes. In contrast, <a href="https://standardebooks.org/ebooks/g-k-chesterton">G. K. Chesterton</a> presents the case for Christianity throughout history, by illustrating firstly, the uniqueness of man amongst the animals, and secondly, the uniqueness of Christ and the Church amongst other religions and philosophies.</p> <p>Written in Chesterton’s typical style, already familiar to readers of <i><a href="https://standardebooks.org/ebo...', 3, 3, 12, 240),
  ((SELECT category_id FROM lib_categories WHERE name='ประวัติศาสตร์'), 'Hidden from History', 'George Chauncey', '9780452010673', 'This richly revealing anthology brings together for the first time the vital new scholarly studies now lifting the veil from the gay and lesbian past. Such notable researchers as John Boswell, Shari Benstock, Carroll Smith-Rosenberg, Jeffrey Weeks and John D’Emilio illuminate gay and lesbian life as it evolved in places as diverse as the Athens of Plato, Renaissance Italy, Victorian London, jazz Age Harlem, Revolutionary Russia, Nazi Germany, Castro’s Cuba, post-World War II San Francisco—and peoples as varied as South African black miners, American Indians, Chinese courtiers, Japanese samurai, English schoolboys and girls, and urban working women.', 4, 4, 9, 180),
  ((SELECT category_id FROM lib_categories WHERE name='ประวัติศาสตร์'), 'A little history of the world', 'E. H. Gombrich', '9780300176148', 'In 1935, with a doctorate in art history and no prospect of a job, the 26-year-old Ernst Gombrich was invited by a publishing acquaintance to attempt a history of the world for younger readers. Amazingly, he completed the task in an intense six weeks, and Eine kurze Weltgeschichte für junge Leser was published in Vienna to immediate success, and is now available in seventeen languages across the world.', 2, 2, 6, 120),
  ((SELECT category_id FROM lib_categories WHERE name='ประวัติศาสตร์'), 'The Age of Revolution', 'Eric Hobsbawm', '9783893400614', 'The Age of Revolution: Europe: 1789–1848 is a book by Eric Hobsbawm, first published in 1962. It is the first in a trilogy of books about "the long 19th century" (coined by Hobsbawm), followed by The Age of Capital: 1848–1875, and The Age of Empire: 1875–1914. A fourth book, The Age of Extremes: The Short Twentieth Century, 1914–1991, acts as a sequel to the trilogy.', 3, 3, 13, 260),
  ((SELECT category_id FROM lib_categories WHERE name='ประวัติศาสตร์'), 'Science and technology in world history', 'James E. McClellan III', '9780801858697', 'In modern industrial society, the tie between science and technology seems clear, even inevitable. But historically, as James E. McClellan III and Harold Dorn remind us, the connection has been far less apparent. For much of human history, technology depended more on the innovation of skilled artisans than it did on the speculation of scientists. Technology as "applied science," the authors argue, emerged relatively recently, as industry and governments began funding scientific research that would lead directly to new or improved technologies. In Science and Technology in World History, McClellan and Dorn offer an introduction to this changing relationship.', 4, 4, 10, 200),
  ((SELECT category_id FROM lib_categories WHERE name='ประวัติศาสตร์'), 'World Restored Europe After Napoleon', 'Henry Kissinger', '9781842120873', NULL, 2, 2, 7, 140),
  ((SELECT category_id FROM lib_categories WHERE name='ประวัติศาสตร์'), 'The age of extremes', 'Eric Hobsbawm', '9780394585758', 'In this masterful and highly accessible study of our times, one of the world''s leading historians sheds exciting new light on our understanding of the twentieth century, with incisive assessments of events that have marked this turbulent period.', 3, 3, 14, 280),
  ((SELECT category_id FROM lib_categories WHERE name='ประวัติศาสตร์'), 'Tragedy and hope', 'Carroll Quigley', '9780026001304', 'TRAGEDY AND HOPE shows the years 1895-1950 as a period of transition from the world dominated by Europe in the nineteenth century to the world of three blocs in the twentieth century. With clarity, perspective, and cumulative impact, Professor Quigley examines the nature of that transition through two world wars and a worldwide economic depression. As an interpretative historian, he tries to show each event in the full complexity of its historical context. The result is a unique work, notable in several ways. It gives a picture of the world in terms of the influence of different cultures and outlooks upon each other; it shows, more completely than in any similar work, the influence of sci...', 4, 4, 11, 220),
  ((SELECT category_id FROM lib_categories WHERE name='ประวัติศาสตร์'), 'World History for Dummies', 'Peter Haugen', '9780470446546', 'The book that puts the "story" back in history!', 2, 2, 8, 160),
  ((SELECT category_id FROM lib_categories WHERE name='ประวัติศาสตร์'), 'Bushidō', 'Inazo Nitobe', '9780342593996', 'RELIGION: GENERAL. Bushido is the chivalric code of moral principles that the Samurai followed. Influenced by Confucianism, Shinto and Zen Buddhism, it tempers the violence of a warrior with wisdom and serenity. This book has become influential among military and corporate leaders looking for ways to manage their people and overcome their opponents. Beautifully produced in traditional Chinese binding and with a timeless design, this book includes the classic Inazo text with a new introduction.', 3, 3, 5, 100),
  ((SELECT category_id FROM lib_categories WHERE name='ประวัติศาสตร์'), 'The Outline of History', 'H. G. Wells', '9780343038007', 'Ben shu shang su ren lei wen ming de kai duan, xia zhi di er ci shi jie da zhan . jiang gu ai ji, gu xi la, gu luo ma, ying guo, mei guo, fa guo deng chao ji da guo de qi luo xing shuai you tiao bu wen di zhan xian zai dou zhe mian qian.', 4, 4, 12, 240),
  ((SELECT category_id FROM lib_categories WHERE name='วรรณกรรมคลาสสิก'), 'Wuthering Heights', 'Emily Brontë', '9782322182732', 'Wuthering Heights is an 1847 novel by Emily Brontë, initially published under the pseudonym Ellis Bell. It concerns two families of the landed gentry living on the West Yorkshire moors, the Earnshaws and the Lintons, and their turbulent relationships with Earnshaw''s adopted son, Heathcliff. The novel was influenced by Romanticism and Gothic fiction.', 2, 2, 9, 180),
  ((SELECT category_id FROM lib_categories WHERE name='วรรณกรรมคลาสสิก'), 'The Prince', 'Niccolò Machiavelli', '9780553897371', 'The Prince (Italian: Il Principe [il ˈprintʃipe]; Latin: De Principatibus) is a 16th-century political treatise written by Italian diplomat and political theorist Niccolò Machiavelli as an instruction guide for new princes and royals. The general theme of The Prince is of accepting that the aims of princes – such as glory and survival – can justify the use of immoral means to achieve those ends.', 3, 3, 6, 120),
  ((SELECT category_id FROM lib_categories WHERE name='วรรณกรรมคลาสสิก'), 'The Invisible Man', 'H. G. Wells', '9781537808352', 'This book is the story of Griffin, a scientist who creates a serum to render himself invisible, and his descent into madness that follows.', 4, 4, 13, 260),
  ((SELECT category_id FROM lib_categories WHERE name='วรรณกรรมคลาสสิก'), 'Moby Dick', 'Herman Melville', '9781547220892', '"Command the murderous chalices! Drink ye harpooners! Drink and swear, ye men that man the deathful whaleboat''s bow -- Death to Moby Dick!" So Captain Ahab binds his crew to fulfil his obsession -- the destruction of the great white whale. Under his lordly but maniacal command the Pequod''s commercial mission is perverted to one of vengeance. To Ahab, the monster that destroyed his body is not a creature, but the symbol of "some unknown but still reasoning thing." Uncowed by natural disasters, ill omens, even death, Ahab urges his ship towards "the undeliverable, nameless perils of the whale."', 2, 2, 10, 200),
  ((SELECT category_id FROM lib_categories WHERE name='วรรณกรรมคลาสสิก'), 'Hamlet', 'William Shakespeare', '9789873874109', 'In this quintessential Shakespeare tragedy, a young prince''s halting pursuit of revenge for the murder of his father unfolds in a series of highly charged confrontations that have held audiences spellbound for nearly four centuries. Those fateful exchanges, and the anguished soliloquies that precede and follow them, probe depths of human feeling rarely sounded in any art.', 3, 3, 7, 140),
  ((SELECT category_id FROM lib_categories WHERE name='วรรณกรรมคลาสสิก'), 'The Time Machine', 'H. G. Wells', '9788175992955', 'The Time Traveller, a dreamer obsessed with traveling through time, builds himself a time machine and, much to his surprise, travels over 800,000 years into the future. He lands in the year 802701: the world has been transformed by a society living in apparent harmony and bliss, but as the Traveler stays in the future he discovers a hidden barbaric and depraved subterranean class. Wells''s transparent commentary on the capitalist society was an instant bestseller and launched the time-travel genre.', 4, 4, 14, 280),
  ((SELECT category_id FROM lib_categories WHERE name='วรรณกรรมคลาสสิก'), 'Jane Eyre', 'Charlotte Brontë', '9781434615701', 'The novel is set somewhere in the north of England. Jane''s childhood at Gateshead Hall, where she is emotionally and physically abused by her aunt and cousins; her education at Lowood School, where she acquires friends and role models but also suffers privations and oppression; her time as the governess of Thornfield Hall, where she falls in love with her Byronic employer, Edward Rochester; her time with the Rivers family, during which her earnest but cold clergyman cousin, St John Rivers, proposes to her. Will she or will she not marry him?', 2, 2, 11, 220),
  ((SELECT category_id FROM lib_categories WHERE name='วรรณกรรมคลาสสิก'), 'The Secret Garden', 'Frances Hodgson Burnett', '9780582426597', 'A ten-year-old orphan comes to live in a lonely house on the Yorkshire moors where she discovers an invalid cousin and the mysteries of a locked garden.', 3, 3, 8, 160),
  ((SELECT category_id FROM lib_categories WHERE name='วรรณกรรมคลาสสิก'), 'A Tale of Two Cities', 'Charles Dickens', '9780192817716', 'A Tale of Two Cities is a historical novel published in 1859 by Charles Dickens, set in London and Paris before and during the French Revolution. The novel tells the story of the French Doctor Manette, his 18-year-long imprisonment in the Bastille in Paris, and his release to live in London with his daughter Lucie whom he had never met. The story is set against the conditions that led up to the French Revolution and the Reign of Terror. In the Introduction to the Encyclopedia of Adventure Fiction, critic Don D''Ammassa argues that it is an adventure novel because the protagonists are in constant danger of being imprisoned or killed.', 4, 4, 5, 100),
  ((SELECT category_id FROM lib_categories WHERE name='วรรณกรรมคลาสสิก'), 'Slaughterhouse-Five', 'Kurt Vonnegut', '9780613647885', 'Slaughterhouse-Five is one of the world''s great anti-war books. Centering on the infamous fire-bombing of Dresden, Billy Pilgrim''s odyssey through time reflects the mythic journey of our own fractured lives as we search for meaning in what we are afraid to know.', 2, 2, 12, 240),
  ((SELECT category_id FROM lib_categories WHERE name='วรรณกรรมคลาสสิก'), 'The War of the Worlds', 'H. G. Wells', '9781412196956', 'The ultimate science fiction classic: for more than one hundred years, this compelling tale of the Martian invasion of Earth has enthralled readers with a combination of imagination and incisive commentary on the imbalance of power that continues to be relevant today. The style is revolutionary for its era, employing a sophisticated first and third person account of the events which is both personal and focused on the holistic downfall of Earth''s society. The Martians, as evil, mechanical and unknown a threat they are, remain daunting in today''s society, where, despite technology''s mammoth advances, humanity''s hegemony over Earth is yet to be called into question. In Well''s introduction t...', 3, 3, 9, 180),
  ((SELECT category_id FROM lib_categories WHERE name='วรรณกรรมคลาสสิก'), 'East of Eden', 'John Steinbeck', '9780140186390', 'Steinbeck considered East of Eden to be his masterpiece. In his journal, Journal of a Novel (often read as a companion to the novel) he notes that “this is the book I have always wanted and have worked and prayed to be able to write Set primarily in the Salinas Valley in the early twentieth century, the novel traces three generations of two families – the Trasks and the Hamiltons – as they grapple with the ever-present forces of good and evil. From this plot emerged some of Steinbeck’s most fascinating characters – many of whom are modeled after people in his own life.', 4, 4, 6, 120),
  ((SELECT category_id FROM lib_categories WHERE name='วรรณกรรมคลาสสิก'), 'Siddhartha', 'Hermann Hesse', '9788484502111', 'Hermann Hesse wrote Siddhartha after he traveled to India in the 1910s. It tells the story of a young boy who travels the country in a quest for spiritual enlightenment in the time of Guatama Buddha. It is a compact, lyrical work, which reads like an allegory about the finding of wisdom.', 2, 2, 13, 260),
  ((SELECT category_id FROM lib_categories WHERE name='วรรณกรรมคลาสสิก'), 'Heart of Darkness', 'Joseph Conrad', '9780582823044', 'Heart of Darkness (1899) is a novella by Polish-English novelist Joseph Conrad, about a voyage up the Congo River into the Congo Free State, in the heart of Africa, by the story''s narrator Charles Marlow. Marlow tells his story to friends aboard a boat anchored on the River Thames. Joseph Conrad is one of the greatest English writers, and Heart of Darkness is considered his best. His readers are brought to face our psychological selves to answer, ‘Who is the true savage?’. Originally published in 1902, Heart of Darkness remains one of this century’s most enduring works of fiction. Written several years after Joseph Conrad’s grueling sojourn in the Belgian Congo, the novel is a complex med...', 3, 3, 10, 200),
  ((SELECT category_id FROM lib_categories WHERE name='วรรณกรรมคลาสสิก'), 'The Grapes of Wrath', 'John Steinbeck', '9780582461536', 'Steinbeck’s classic novel of the Great Depression is as vivid now as ever. The story focuses on a family of Oklahoma sharecroppers, farmers who work another man’s land for a share of the crops. Driven from their home by drought and poverty they take to the road in a battered old truck and make their way to California to look for work. When they arrive they find hundreds of others like them being forced to work for breadline wages. they begin working as fruit pickers, strike-breakers replacing the people who have been trying to establish a union but their consciences force them to leave.', 4, 4, 7, 140),
  ((SELECT category_id FROM lib_categories WHERE name='วรรณกรรมคลาสสิก'), 'Great Expectations', 'Charles Dickens', '9781374822900', 'Great Expectations is the thirteenth novel by Charles Dickens and his penultimate completed novel. It depicts the education of an orphan nicknamed Pip (the book is a bildungsroman; a coming-of-age story). It is Dickens'' second novel, after David Copperfield, to be fully narrated in the first person. The novel was first published as a serial in Dickens''s weekly periodical All the Year Round, from 1 December 1860 to August 1861. In October 1861, Chapman and Hall published the novel in three volumes.', 2, 2, 14, 280),
  ((SELECT category_id FROM lib_categories WHERE name='วรรณกรรมคลาสสิก'), 'Where the Red Fern Grows', 'Wilson Rawls', '9781432850326', 'Where the Red Fern Grows is a 1961 children''s novel by Wilson Rawls about a boy who buys two hunting dogs.', 3, 3, 11, 220),
  ((SELECT category_id FROM lib_categories WHERE name='วรรณกรรมคลาสสิก'), 'A Christmas Carol', 'Charles Dickens', '9781853261213', 'A reprinting of the 1843 first edition, complete with the original illustrations, is supplemented by over eighty related sketches and annotations on and analyses of the text and historical notes on the writing of "The Christmas Carol."', 4, 4, 8, 160),
  ((SELECT category_id FROM lib_categories WHERE name='วรรณกรรมคลาสสิก'), 'The Complete Sherlock Holmes [4 novels, 56 stories]', 'Arthur Conan Doyle', '9780713914443', 'Contains:', 2, 2, 5, 100),
  ((SELECT category_id FROM lib_categories WHERE name='วรรณกรรมคลาสสิก'), 'Don Quijote de la Mancha', 'Miguel de Cervantes Saavedra', '9783538068926', 'Don Quijote de la Mancha es una novela escrita por el español Miguel de Cervantes Saavedra. Publicada su primera parte con el título de El ingenioso hidalgo don Quijote de la Mancha a comienzos de 1605, es la obra más destacada de la literatura española y una de las principales de la literatura universal. En 1615 apareció su continuación con el título de Segunda parte del ingenioso caballero don Quijote de la Mancha. Es la primera obra genuinamente desmitificadora de la tradición caballeresca y cortés por su tratamiento burlesco. Representa la primera novela moderna y la primera novela polifónica; como tal, ejerció un enorme influjo en toda la narrativa europea. La novela ha sido ca...', 3, 3, 12, 240),
  ((SELECT category_id FROM lib_categories WHERE name='วรรณกรรมคลาสสิก'), 'A Midsummer Night''s Dream', 'William Shakespeare', '9788489163881', 'One night two young couples run into an enchanted forest in an attempt to escape their problems. But these four humans do not realize that the forest is filled with fairies and hobgoblins who love making mischief. When Oberon, the Fairy King, and his loyal hobgoblin servant, Puck, intervene in human affairs, the fate of these young couples is magically and hilariously transformed. Like a classic fairy tale, this retelling of William Shakespeare''s most beloved comedy is perfect for older readers who will find much to treasure and for younger readers who will love hearing the story read aloud.', 4, 4, 9, 180),
  ((SELECT category_id FROM lib_categories WHERE name='วรรณกรรมคลาสสิก'), 'Alice''s Adventures in Wonderland / Through the Looking Glass', 'Lewis Carroll', '9788426398550', 'A very real little girl named Alice follows a remarkable rabbit down a rabbit hole and steps through a looking-glass to come face to face with some of the strangest adventures and some of the oddest characters in all literature. The crusty Duchess, the Mad Hatter, the weeping Mock Turtle, the diabolical Queen of Hearts, the Cheshire-Cat, Tweedledum and Tweedledee--each one is more eccentric, and more entertaining, than the last. And all of them could only have come from the pen of Lewis Carroll, one of the few adults ever to enter successfully the children''s world of make-believe--a wonderland where the impossible becomes possible, the unreal, real...where the heights of adventure are lim...', 2, 2, 6, 120),
  ((SELECT category_id FROM lib_categories WHERE name='วรรณกรรมคลาสสิก'), 'The Mysterious Affair at Styles', 'Agatha Christie', '9780396072249', 'Set in the summer of 1917 in an Essex country estate, the story follows the war-wounded Captain Arthur Hastings to the Styles St. Mary manor of his friend John Cavendish. The Cavendish household is wrought with tension due to the marriage of John''s widowed old aunt Emily, she of a sizeable fortune, to a suspicious younger man, Alfred Inglethorp, twenty years her junior. Emily''s two stepsons, John and Lawrence Cavendish, as well as John''s wife Mary and several other people, also live at Styles. Late one night, the residents of Styles wake to find Emily Inglethorp dying. When Emily''s sudden heart attack is found to be attributable to strychnine, Hastings, who had runs into his old friend, t...', 3, 3, 13, 260),
  ((SELECT category_id FROM lib_categories WHERE name='วรรณกรรมคลาสสิก'), 'War and Peace', 'Лев Толстой', '9780736603706', 'War and Peace delineates in graphic detail events surrounding the French invasion of Russia, and the impact of the Napoleonic era on Tsarist society, as seen through the eyes of five Russian aristocratic families. The novel begins in the year 1805 during the reign of Tsar Alexander I and leads up to the 1812 French invasion of Russia by Napoleon. The era of Catherine the Great (1762–1796), when the royal court in Paris was the centre of western European civilization,[16] is still fresh in the minds of older people. Catherine, fluent in French and wishing to reshape Russia into a great European nation, made French the language of her royal court. For the next one hundred years, it became a...', 4, 4, 10, 200),
  ((SELECT category_id FROM lib_categories WHERE name='คอมพิวเตอร์'), 'Introduction to Algorithms', 'Thomas H. Cormen', '9780070131514', 'This book provides a comprehensive introduction to the modern study of computer algorithms. It presents many algorithms and covers them in considerable depth, yet makes their design and analysis accessible to all levels of readers. We have tried to keep explanations elementary without sacrificing depth of coverage or mathematical rigor. Each chapter presents an algorithm, a design technique, an application area, or a related topic. Algorithms are described in English and in a "pseudocode" designed to be readable by anyone who has done a little programming. The book contains over 260 figrues illustrating how the algorithms work. Since we emphasize efficiency as a design criterion, we inclu...', 2, 2, 7, 140),
  ((SELECT category_id FROM lib_categories WHERE name='คอมพิวเตอร์'), 'Software Engineering', 'Roger S. Pressman', '9788448132149', NULL, 3, 3, 14, 280),
  ((SELECT category_id FROM lib_categories WHERE name='คอมพิวเตอร์'), 'The Pragmatic Programmer', 'Andy Hunt', '9788131722428', 'The Pragmatic Programmer is one of those rare tech audiobooks you’ll listen, re-listen, and listen to again over the years. Whether you’re new to the field or an experienced practitioner, you’ll come away with fresh insights each and every time.', 4, 4, 11, 220),
  ((SELECT category_id FROM lib_categories WHERE name='คอมพิวเตอร์'), 'Hackers', 'Steven Levy', '9780140232691', 'Today, technology is cool. Owning the most powerful computer, the latest high-tech gadget, and the whizziest website is a status symbol on a par with having a flashy car or a designer suit. And a media obsessed with the digital explosion has reappropriated the term "computer nerd" so that it''s practically synonymous with "entrepreneur." Yet, a mere fifteen years ago, wireheads hooked on tweaking endless lines of code were seen as marginal weirdos, outsiders whose world would never resonate with the mainstream. That was before one pioneering work documented the underground computer revolution that was about to change our world forever.', 2, 2, 8, 160),
  ((SELECT category_id FROM lib_categories WHERE name='คอมพิวเตอร์'), 'JavaScript', 'David Flanagan', '9788565837194', 'JavaScript is a powerful, object-based scripting language; JavaScript programs can be embedded directly into HTML web pages. When combined with the Document Object Model (DOM) defined by a web browser, JavaScript allows you to create Dynamic HTML (DHTML) content and interactive client-side web applications. JavaScript syntax is based on the popular programming languages C, C++, and Java, which makes it familiar and easy to learn for experienced programmers. At the same time, JavaScript is an interpreted scripting language, providing a flexible, forgiving environment in which new programmers can learn.', 3, 3, 5, 100),
  ((SELECT category_id FROM lib_categories WHERE name='คอมพิวเตอร์'), 'Automate the Boring Stuff with Python', 'Al Sweigart', '9781593279929', 'If you''ve ever spent hours renaming files or updating hundreds of spreadsheet cells, you know how tedious tasks like these can be. But what if you could have your computer do them for you? In Automate the Boring Stuff with Python, you''ll learn how to use Python to write programs that do in minutes what would take you hours to do by hand—no prior programming experience required. Once you''ve mastered the basics of programming, you''ll create Python programs that effortlessly perform useful and impressive feats of automation to:', 4, 4, 12, 240),
  ((SELECT category_id FROM lib_categories WHERE name='คอมพิวเตอร์'), 'The art of computer programming', 'Donald Knuth', '9780201853933', NULL, 2, 2, 9, 180),
  ((SELECT category_id FROM lib_categories WHERE name='คอมพิวเตอร์'), 'Structure and Interpretation of Computer Programs (SICP)', 'Harold Abelson', '9780262510875', 'Wizard Book n. Hal Abelson''s, Jerry Sussman''s and Julie Sussman''s Structure and Interpretation of Computer Programs (MIT Press, 1984; ISBN 0-262-01077-1), an excellent computer science text used in introductory courses at MIT. So called because of the wizard on the jacket. One of the bibles of the LISP/Scheme world. Also, less commonly, known as the Purple Book.', 3, 3, 6, 120),
  ((SELECT category_id FROM lib_categories WHERE name='คอมพิวเตอร์'), 'The Mythical Man-Month', 'Frederick P. Brooks', '9780201006506', 'Classic text on the human side of software engineering, containing essays on the management of software teams, projections about how computer languages and tools will evolve, and philosophical speculation. Unlike most other books about computing, Brooks'' work has been remarkably enduring, remaining in print for at least four decades. The book is most famous for its statement of Brooks'' Law: "adding manpower to a late software project makes it later".', 4, 4, 13, 260),
  ((SELECT category_id FROM lib_categories WHERE name='คอมพิวเตอร์'), 'Code', 'Charles Petzold', '9780735605053', 'What do flashlights, the British invasion, black cats, and seesaws have to do with computers? In CODE, they show us the ingenious ways we manipulate language and invent new means of communicating with each other. And through CODE, we see how this ingenuity and our very human compulsion to communicate have driven the technological innovations of the past two centuries.', 2, 2, 10, 200),
  ((SELECT category_id FROM lib_categories WHERE name='คอมพิวเตอร์'), 'The C++ programming language', 'Bjarne Stroustrup', '9783827316608', 'The C++ Programming tome, written by the father of C++ himself, Bjarne Stroustrup. The premier book on the subject of C++ Programming.', 3, 3, 7, 140),
  ((SELECT category_id FROM lib_categories WHERE name='คอมพิวเตอร์'), 'Fluent Python', 'Luciano Ramalho', '9788575224625', NULL, 4, 4, 14, 280),
  ((SELECT category_id FROM lib_categories WHERE name='คอมพิวเตอร์'), 'Clean Architecture', 'Robert C. Martin', '9789352865123', NULL, 2, 2, 11, 220),
  ((SELECT category_id FROM lib_categories WHERE name='คอมพิวเตอร์'), 'Programming in ANSI C', 'E. Balagurusamy', '9780070681828', NULL, 3, 3, 8, 160),
  ((SELECT category_id FROM lib_categories WHERE name='คอมพิวเตอร์'), 'SQL for Dummies', 'Allen G. Taylor', '9782746404137', 'Learn SQL the fun and easy way -- no programming experience needed! SQL For Dummies, 7th Edition, shows programmers and web developers how to use SQL to build relational databases and get valuable information from them. This book covers the core features of the SQL language. Topics covered include how to use SQL to structure a DBMS and implement a database design; secure a database; and retrieve information from a database. This edition will be revised to reflect the new enhancements of SQL/XML:2008. The latest update of the perennial bestselling SQL For Dummies, which has sold more than 210,000 units in six editions. SQL is the most popular database language in the world Covers creating,...', 4, 4, 5, 100),
  ((SELECT category_id FROM lib_categories WHERE name='คอมพิวเตอร์'), 'C programming', 'K. N. King', '9788838785825', NULL, 2, 2, 12, 240),
  ((SELECT category_id FROM lib_categories WHERE name='คอมพิวเตอร์'), 'C++', 'Paul J. Deitel', '9781782369219', 'Publisher''s description: For Introduction to Programming (CS1) and other more intermediate courses covering programming in C++. Also appropriate as a supplement for upper-level courses where the instructor uses a book as a reference for the C++ language. This best-selling comprehensive text is aimed at readers with little or no programming experience. It teaches programming by presenting the concepts in the context of full working programs and takes and early objects approach. The text has an emphasis on achieving program clarity through structured and object-oriented programming, software reuse and component-oriented software construction. The Sixth Edition reflects the suggested impro...', 3, 3, 9, 180),
  ((SELECT category_id FROM lib_categories WHERE name='คอมพิวเตอร์'), 'Grokking Algorithms', 'Aditya Y. Bhargava', '9781617292231', '"Grokking Algorithms is a fully illustrated, friendly guide that teaches you how to apply common algorithms to the practical problems you face every day as a programmer. You''ll start with sorting and searching and, as you build up your skills in thinking algorithmically, you''ll tackle more complex concerns such as data compression and artificial intelligence. Each carefully presented example includes helpful diagrams and fully annotated code samples in Python."--Publisher''s desription.', 4, 4, 6, 120),
  ((SELECT category_id FROM lib_categories WHERE name='คอมพิวเตอร์'), 'The clean coder', 'Robert C. Martin', '9780137081073', 'In the <i>Clean Coder: A Code of Conduct for Professional Programmers</i>, legendary software expert Robert C Martin introduces the disciplines, techniques, tools, and practices of true software craftsmanship.', 2, 2, 13, 260),
  ((SELECT category_id FROM lib_categories WHERE name='คอมพิวเตอร์'), 'System Design Interview - an Insider''s Guide', 'Alex Xu', '9781736049112', 'An insider''s take on what interviewers are really looking for and why including: a 4-step framework for solving any system design interview question and 16 real system design interview questions with detailed solutions.', 3, 3, 10, 200),
